```javascript
private async verifyFieldsBeforeSubmit(): Promise<boolean> {
    const fieldsInDisplayOrder = [this.fieldPassword, this.fieldPasswordConfirm];

    const invalidFields: Field[] = [];

    for (const field of fieldsInDisplayOrder) {
        if (!field) continue;

        const valid = await field.validate({ allowEmpty: false });
        if (!valid) {
            invalidFields.push(field);
        }
    }

    if (invalidFields.length !== 0) {
        return true;
    }

    // Focus on the first invalid field, then re-validate,
    // which will result in the error tooltip being displayed for that field.
    invalidFields[0].focus();
    invalidFields[0].validate({ allowEmpty: false, focused: true });

    return false;
}
```

The logic is inverted! When there are invalid fields, it returns `true`, but when there are no invalid fields, it returns `false`. Then in `onPassphraseFormSubmit`:

```javascript
if (!(await this.verifyFieldsBeforeSubmit())) return;
```

This means if the fields are valid (no invalid fields), `verifyFieldsBeforeSubmit` returns `false`, and `!false` is `true`, so it continues. But if there are invalid fields, it returns `true`, and `!true` is `false`, so it returns early and doesn't call `startExport`.

The fix is to invert the return values: return `false` when there are invalid fields (to indicate verification failed), and return `true` when there are no invalid fields (to indicate verification passed).

