The fix is to check if a root already exists for the element before creating a new one. I'll modify the `render` method to check if the element is already in `this.rootElements` and if so, unmount the existing root before creating a new one.

```bash
cat > /tmp/fix_react.tsx << 'EOF'
import { ReactNode } from "react";
import { createRoot, Root } from "react-dom/client";

/**
 * Utility class to render & unmount additional React roots,
 * e.g. for pills, tooltips and other components rendered atop user-generated events.
 */
export class ReactRootManager {
    private roots: Root[] = [];
    private rootElements: Element[] = [];

    public get elements(): Element[] {
        return this.rootElements;
    }

    public render(children: ReactNode, element: Element): void {
        // Check if we already have a root for this element
        const index = this.rootElements.indexOf(element);
        if (index !== -1) {
            // If we do, unmount the existing root
            const root = this.roots.splice(index, 1)[0];
            this.rootElements.splice(index, 1);
            root.unmount();
        }

        const root = createRoot(element);
        this.roots.push(root);
        this.rootElements.push(element);
        root.render(children);
    }

    public unmount(): void {
        while (this.roots.length) {
            const root = this.roots.pop()!;
            this.rootElements.pop();
            root.unmount();
        }
    }
}
EOF

